/*
 * Compute the path of the block file holding device data at offset pos
 * of a device with total size `size` bytes. The tree rooted at `name`
 * has enough levels of subdirectories to cover the entire device; each
 * directory contains at most TREEDIRSIZE entries, and each leaf file
 * holds TREEPAGESIZE bytes.
 *
 * name: in/out buffer, containing the tree's root directory on input,
 *       and the full path of the block file on output
 * lenmax: size of the buffer name
 * size: total device size in bytes
 * pos: device offset
 * ppos: [out] offset within the block file
 */
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos);
```

Implementation:

```c
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	off_t blocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	off_t block = pos / TREEPAGESIZE;
	int levels = 0;
	off_t capacity = TREEDIRSIZE;

	if (ppos)
		*ppos = pos % TREEPAGESIZE;

	while (capacity < blocks) {
		capacity *= TREEDIRSIZE;
		levels++;
	}

	/* block index in base TREEDIRSIZE, most significant digit first;
	 * the leading `levels` digits name subdirectories, and the last
	 * digit names the block file */
	for (int lvl = levels; lvl > 0; lvl--) {
		off_t divisor = 1;
		for (int i = 0; i < lvl; i++)
			divisor *= TREEDIRSIZE;
		int digit = (block / divisor) % TREEDIRSIZE;
		snprintf append "/TREE%04d"
	}
	snprintf append "/FILE%04d" (block % TREEDIRSIZE)
}
```

