```c
/*
 * Read from a treefiles export. Reads are limited to the block file
 * containing the first byte, so a single read never spans multiple
 * block files; the caller loops until the request is satisfied.
 */
static ssize_t treefiles_read(off_t a, char *buf, size_t len, CLIENT *client) {
	off_t ppos = a % TREEPAGESIZE;
	ssize_t ret;
	int fhandle;

	if (len > (size_t)(TREEPAGESIZE - ppos))
		len = TREEPAGESIZE - ppos;

	fhandle = open_treefile(client->exportname, O_RDONLY,
				(off_t)client->exportsize, a, &client->tree_lock);
	if (fhandle < 0) {
		if (errno == ENOENT) {
			/* Never-written blocks read back as zeros */
			memset(buf, 0, len);
			return len;
		}
		return -1;
	}
	ret = pread(fhandle, buf, len, ppos);
	if (ret >= 0 && (size_t)ret < len) {
		/* Block file is shorter than the block; e.g. after a
		 * partial write. The remainder reads back as zeros. */
		memset(buf + ret, 0, len - ret);
		ret = len;
	}
	close(fhandle);
	return ret;
}
```

