static int trim_treefiles(struct nbd_request *req, CLIENT *client) {
	off_t from = req->from;
	off_t end = from + req->len;
	off_t blkstart;
	off_t blk;

	for (blk = from / TREEPAGESIZE; blk * TREEPAGESIZE < end; blk++) {
		blkstart = blk * TREEPAGESIZE;
		if (from <= blkstart && blkstart + TREEPAGESIZE <= end) {
			/* Fully covered block: drop the file */
			delete_treefile(client->exportname, client->exportsize, blkstart);
		} else {
			/* Partially covered block: punch out only the trimmed bytes */
			off_t ppos = from > blkstart ? from - blkstart : 0;
			off_t plen = ...min(TREEPAGESIZE - ppos, end - (blkstart+ppos));
			int fd = open_treefile(client->exportname, O_RDWR, client->exportsize, blkstart, &client->tree_lock);
			if (fd >= 0) {
				punch_hole(fd, ppos, plen);
				close(fd);
			} else if (errno != ENOENT) {
				return -1;
			}
		}
	}
	return 0;
}
