arguments.content:
/*
 * Tree files support for nbd-server.
 *
 * A treefiles export stores the exported device's data in a tree of
 * small block files: every file holds TREEPAGESIZE bytes of device
 * data, every directory holds at most TREEDIRSIZE entries, and enough
 * levels of subdirectories are used for the tree to cover the full
 * size of the export. This allows exporting large virtual block
 * devices on filesystems that do not handle large files well
 * (fuse/ftpfs, davfs and other network filesystems). See the
 * "treefiles" option in nbd-server(5).
 */

#include "lfs.h"

#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#include "treefiles.h"

/* Maximum number of levels of subdirectories. Each level multiplies
 * the number of blocks the tree can hold by TREEDIRSIZE, so
 * TREE_MAXLEVELS levels can address TREEDIRSIZE^(TREE_MAXLEVELS+1)
 * blocks, which is much more than can fit in a device whose size fits
 * in an off_t. */
#define TREE_MAXLEVELS 6

/* Length of a path component below the tree's root, including the
 * leading slash and the terminating NUL ("/TREEXXXX\0"). */
#define TREE_COMPONENT_LEN 10

/*
 * Compute the path of the block file that holds the device data at
 * offset pos of a device of size bytes, in the tree rooted at name.
 *
 * name is an in/out buffer of lenmax bytes: on entry it must contain
 * the path of the tree's root directory, on return it contains the
 * full path of the block file. If ppos is not NULL, it is set to the
 * offset of pos within that block file.
 */
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	off_t blocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	off_t block = pos / TREEPAGESIZE;
	off_t capacity = TREEDIRSIZE;
	off_t divisor;
	int levels = 0;
	int len;
	int i;

	if(ppos) {
		*ppos = pos % TREEPAGESIZE;
	}

	while(capacity < blocks && levels < TREE_MAXLEVELS) {
		capacity *= TREEDIRSIZE;
		levels++;
	}

	/* Split the block number in levels+1 digits, base
	 * TREEDIRSIZE, most significant digit first. The first
	 * "levels" digits select a subdirectory at each level, the
	 * last one selects the block file within that directory. */
	len = strlen(name);
	divisor = capacity / TREEDIRSIZE;
	for(i = 0; i < levels; i++) {
		int dirnum = (int)((block / divisor) % TREEDIRSIZE);

		if(len < lenmax) {
			len += snprintf(name + len, lenmax - len,
					"/TREE%04d", dirnum);
		}
		divisor /= TREEDIRSIZE;
	}
	if(len < lenmax) {
		snprintf(name + len, lenmax - len, "/FILE%04d",
			 (int)(block % TREEDIRSIZE));
	}
}

/*
 * Create all directories in path, which is interpreted as the path of
 * a file: every component up to, but not including, the last one is
 * created as a directory if it does not exist yet. Errors are
 * ignored; they will surface when the file itself is opened.
 */
void mkdir_path(char *path) {
	char *sep;

	sep = strchr(path + 1, '/');
	while(sep) {
		*sep = '\0';
		mkdir(path, 0700);
		*sep = '/';
		sep = strchr(sep + 1, '/');
	}
}

/*
 * Open the block file holding the device data at offset pos of a
 * device of size bytes, in the tree rooted at name.
 *
 * If mode includes O_CREAT, any missing directories and the block
 * file itself are created; otherwise -1 is returned with errno set to
 * ENOENT if the block file does not exist yet. mutex serializes the
 * creation of directories and files, so that concurrent threads do
 * not race on the same paths.
 *
 * Returns a file descriptor opened with mode, or -1 on error.
 */
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[strlen(name) + (TREE_MAXLEVELS + 1) * TREE_COMPONENT_LEN + 1];
	int fd;

	if(mode & O_CREAT) {
		pthread_mutex_lock(mutex);
		strcpy(path, name);
		construct_path(path, sizeof(path), size, pos, NULL);
		mkdir_path(path);
		fd = open(path, mode, 0600);
		pthread_mutex_unlock(mutex);
	} else {
		strcpy(path, name);
		construct_path(path, sizeof(path), size, pos, NULL);
		fd = open(path, mode);
	}

	return fd;
}

/*
 * Delete the block file holding the device data at offset pos of a
 * device of size bytes, in the tree rooted at name. Silently does
 * nothing if the file does not exist.
 */
void delete_treefile(char *name, off_t size, off_t pos) {
	char path[strlen(name) + (TREE_MAXLEVELS + 1) * TREE_COMPONENT_LEN + 1];

	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, NULL);
	unlink(path);
}

