/**
 * Read an amount of bytes at a given offset from a treefiles export.
 * Reads never cross block files, so a single call serves at most the
 * remainder of the block file containing offset a; the caller loops
 * until the request has been satisfied.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an error
 **/
static ssize_t treefiles_read(off_t a, char *buf, size_t len, CLIENT *client) {
	off_t ppos = a % TREEPAGESIZE;
	int fhandle;
	ssize_t ret;

	if(len > (size_t)(TREEPAGESIZE - ppos))
		len = TREEPAGESIZE - ppos;

	fhandle = open_treefile(client->exportname, O_RDONLY,
			(off_t)client->exportsize, a, &client->tree_lock);
	if(fhandle < 0) {
		if(errno == ENOENT) {
			/* Blocks that were never written read back as
			 * zeroes */
			memset(buf, 0, len);
			return len;
		}
		return -1;
	}
	ret = pread(fhandle, buf, len, ppos);
	if(ret >= 0 && (size_t)ret < len) {
		/* Block file is shorter than a full block, e.g. after
		 * a partial write; the remainder reads back as
		 * zeroes */
		memset(buf + ret, 0, len - ret);
		ret = len;
	}
	close(fhandle);

	return ret;
}

/**
 * Write an amount of bytes at a given offset to a treefiles export.
 * Writes never cross block files, so a single call writes at most the
 * remainder of the block file containing offset a; the caller loops
 * until the request has been satisfied.
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're serving for
 * @param fua Flag to indicate 'Force Unit Access'
 * @return The number of bytes actually written, or -1 in case of an error
 **/
static ssize_t treefiles_write(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	off_t ppos = a % TREEPAGESIZE;
	int fhandle;
	ssize_t ret;

	if(len > (size_t)(TREEPAGESIZE - ppos))
		len = TREEPAGESIZE - ppos;

	fhandle = open_treefile(client->exportname, O_RDWR | O_CREAT,
			(off_t)client->exportsize, a, &client->tree_lock);
	if(fhandle < 0)
		return -1;
	ret = pwrite(fhandle, buf, len, ppos);
	if(ret >= 0) {
		if(client->server->flags & F_SYNC) {
			fsync(fhandle);
		} else if(fua) {
			fdatasync(fhandle);
		}
	}
	close(fhandle);

	return ret;
}

