static void rm_rf(const char *path) {
	struct dirent *de;
	DIR *dirh;
	char buf[4096];

	if((dirh = opendir(path))) {
		while((de = readdir(dirh))) {
			if(!strcmp(de->d_name, ".") || !strcmp(de->d_name, ".."))
				continue;
			snprintf(buf, sizeof buf, "%s/%s", path, de->d_name);
			rm_rf(buf);
		}
		closedir(dirh);
		rmdir(path);
