	construct_path(strcpy(path, root), sizeof path, (off_t)1024*1024*1024*TREEPAGESIZE, (off_t)(TREEDIRSIZE*TREEDIRSIZE+TREEDIRSIZE+1)*TREEPAGESIZE, NULL);
	count_assert(!strcmp(path + strlen(root), "/TREE0001/TREE0001/FILE0001"));

	/* open_treefile creates directories and files on demand */
	fd = open_treefile(root, O_RDWR | O_CREAT, 1024*1024*TREEPAGESIZE, (off_t)(TREEDIRSIZE+1)*TREEPAGESIZE, &mutex);
