	memset(buf, 'A', sizeof buf);
	count_assert(pwrite(fd, buf, TREEPAGESIZE, 0) == TREEPAGESIZE);
	close(fd);

	strcpy(path, root);
	construct_path(path, sizeof path, 1024*1024*TREEPAGESIZE, (off_t)(TREEDIRSIZE+1)*TREEPAGESIZE, NULL);
	count_assert(access(path, F_OK) == 0);

	/* data can be read back */
	fd = open_treefile(root, O_RDONLY, 1024*1024*TREEPAGESIZE, (off_t)(TREEDIRSIZE+1)*TREEPAGESIZE, &mutex);
	count_assert(fd >= 0);
	memset(buf, 0, sizeof buf);
	count_assert(pread(fd, buf, TREEPAGESIZE, 0) == TREEPAGESIZE);
	count_assert(buf[0] == 'A' && buf[TREEPAGESIZE-1] == 'A');
	close(fd);

	/* reading a block that was never written fails with ENOENT */
	fd = open_treefile(root, O_RDONLY, 1024*1024*TREEPAGESIZE, 0, &mutex);
	count_assert(fd < 0 && errno == ENOENT);

	/* delete_treefile removes the block file... */
	delete_treefile(root, 1024*1024*TREEPAGESIZE, (off_t)(TREEDIRSIZE+1)*TREEPAGESIZE);
	count_assert(access(path, F_OK) < 0);

	/* ...and does nothing if it's already gone */
	delete_treefile(root, 1024*1024*TREEPAGESIZE, (off_t)(TREEDIRSIZE+1)*TREEPAGESIZE);

	rm_rf(root);

	return 0;
}
