arguments.content:
/*
 * End-to-end test client for the treefiles export option.
 *
 * Connects to a treefiles export using the plain newstyle protocol,
 * writes a deterministic pattern (depending only on the offset) at
 * various offsets -- including unaligned ones and ones that require
 * multiple levels of subdirectories -- and reads it back, either in
 * the same connection or after reconnecting. Also verifies that
 * unwritten areas read back as zeroes, and that TRIM turns trimmed
 * areas back into zeroes.
 *
 * Usage:
 *   tree-e2e-client write host port exportname
 *   tree-e2e-client verify host port exportname
 *   tree-e2e-client trimtest host port exportname
 *   tree-e2e-client expect offset length > file
 */

#include "lfs.h"

#include <arpa/inet.h>
#include <errno.h>
#include <inttypes.h>
#include <netdb.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <unistd.h>

#define NBD_REQUEST_MAGIC 0x25609513
#define NBD_REPLY_MAGIC 0x67446698
#define NBD_CMD_READ 0
#define NBD_CMD_WRITE 1
#define NBD_CMD_DISC 2
#define NBD_CMD_FLUSH 3
#define NBD_CMD_TRIM 4

#define INIT_PASSWD "NBDMAGIC"
#define OPTS_MAGIC 0x49484156454F5054ULL
#define NBD_OPT_EXPORT_NAME 1

/* Export size used by the treee2e test in simple_test: 8 GiB +
 * 8 MiB, which needs 2099200 blocks, and hence two levels of
 * subdirectories */
#define EXPSIZE 8598323200ULL

struct nbd_request {
	uint32_t magic;
	uint32_t type;
	uint64_t cookie;
	uint64_t from;
	uint32_t len;
} __attribute__((packed));

struct nbd_reply {
	uint32_t magic;
	uint32_t error;
	uint64_t cookie;
} __attribute__((packed));

static uint64_t htonll(uint64_t a) {
	uint32_t lo = htonl((uint32_t)a);
	uint32_t hi = htonl((uint32_t)(a >> 32));

	return ((uint64_t)lo << 32) | hi;
}

#define ntohll htonll

static const char *errstr = "no error";

static int xwrite(int fd, const void *buf, size_t len) {
	const char *p = buf;

	while (len) {
		ssize_t res = write(fd, p, len);

		if (res <= 0) {
			errstr = strerror(errno);
			return -1;
		}
		p += res;
		len -= res;
	}
	return 0;
}

static int xread(int fd, void *buf, size_t len) {
	char *p = buf;

	while (len) {
		ssize_t res = read(fd, p, len);

		if (res <= 0) {
			errstr = res ? strerror(errno) : "unexpected EOF";
			return -1;
		}
		p += res;
		len -= res;
	}
	return 0;
}

/* deterministic pattern: depends only on the offset, so overlapping
 * writes never conflict */
static unsigned char pat(uint64_t off) {
	return (unsigned char)(off ^ (off >> 8) ^ 0xA5);
}

static void fill_pattern(char *buf, uint64_t off, size_t len) {
	size_t i;

	for (i = 0; i < len; i++)
		buf[i] = (char)pat(off + i);
}

static int connect_server(const char *host, const char *port) {
	struct addrinfo hints, *ai;
	int sock;
	int e;

	memset(&hints, 0, sizeof(hints));
	hints.ai_family = AF_UNSPEC;
	hints.ai_socktype = SOCK_STREAM;
	if ((e = getaddrinfo(host, port, &hints, &ai))) {
		fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(e));
		return -1;
	}
	sock = socket(ai->ai_family, ai->ai_socktype, ai->ai_protocol);
	if (sock < 0) {
		errstr = strerror(errno);
		freeaddrinfo(ai);
		return -1;
	}
	if (connect(sock, ai->ai_addr, ai->ai_addrlen) < 0) {
		errstr = strerror(errno);
		close(sock);
		freeaddrinfo(ai);
		return -1;
	}
	freeaddrinfo(ai);
	return sock;
}

/*
 * Do the newstyle handshake for the given export; returns a socket in
 * transmission phase and reports the export size. Returns -1 on
 * error.
 */
static int negotiate(const char *host, const char *port,
		const char *name, uint64_t *size) {
	char magic[8];
	uint64_t opts;
	uint16_t gflags;
	uint32_t cflags = 0;
	struct {
		uint64_t magic;
		uint32_t opt;
		uint32_t len;
	} __attribute__((packed)) reqhdr;
	char zeroes[124];
	uint16_t eflags;
	int sock;

	sock = connect_server(host, port);
	if (sock < 0)
		return -1;
	if (xread(sock, magic, 8) || memcmp(magic, INIT_PASSWD, 8)) {
		errstr = "bad initial magic";
		goto err;
	}
	if (xread(sock, &opts, 8) || ntohll(opts) != OPTS_MAGIC) {
		errstr = "bad options magic";
		goto err;
	}
	if (xread(sock, &gflags, 2)) {
		errstr = "short read of global flags";
		goto err;
	}
	if (xwrite(sock, &cflags, 4))
		goto err;
	reqhdr.magic = htonll(OPTS_MAGIC);
	reqhdr.opt = htonl(NBD_OPT_EXPORT_NAME);
	reqhdr.len = htonl(strlen(name));
	if (xwrite(sock, &reqhdr, sizeof(reqhdr)))
		goto err;
	if (xwrite(sock, name, strlen(name)))
		goto err;
	if (xread(sock, size, 8)) {
		errstr = "short read of export size";
		goto err;
	}
	*size = ntohll(*size);
	if (xread(sock, &eflags, 2)) {
		errstr = "short read of export flags";
		goto err;
	}
	if (xread(sock, zeroes, sizeof(zeroes))) {
		errstr = "short read of reserved zeroes";
		goto err;
	}
	return sock;
err:
	close(sock);
	return -1;
}

static int do_request(int sock, uint32_t type, uint64_t from, uint32_t len,
		const void *wdata, void *rdata, uint32_t *error) {
	struct nbd_request req;
	struct nbd_reply rep;

	req.magic = htonl(NBD_REQUEST_MAGIC);
	req.type = htonl(type);
	req.cookie = htonll(from);
	req.from = htonll(from);
	req.len = htonl(len);
	if (xwrite(sock, &req, sizeof(req)))
		return -1;
	if (type == NBD_CMD_WRITE && xwrite(sock, wdata, len))
		return -1;
	if (type == NBD_CMD_DISC)
		return 0;
	if (xread(sock, &rep, sizeof(rep)))
		return -1;
	if (ntohl(rep.magic) != NBD_REPLY_MAGIC) {
		errstr = "bad reply magic";
		return -1;
	}
	if (rep.cookie != htonll(from)) {
		errstr = "cookie mismatch";
		return -1;
	}
	if (error)
		*error = ntohl(rep.error);
	if (ntohl(rep.error))
		return 0;
	if (type == NBD_CMD_READ && xread(sock, rdata, len))
		return -1;
	return 0;
}

/* the offsets we write at, and read back in verify mode */
static struct io {
	uint64_t off;
	uint32_t len;
} ios[] = {
	{0, 4096},
	{100, 100},					/* unaligned */
	{4000, 8284},		/* crossing multiple block boundaries */
	{8388608, 4096},				/* block 2048 */
	{4ULL * 1024 * 1024 * 1024, 4096},		/* block 1048576 */
	{5ULL * 1024 * 1024 * 1024 + 8388608, 4096},	/* block 1312768 */
	{EXPSIZE - 4096, 4096},				/* last block */
	{EXPSIZE - 100, 100},				/* end of device */
};

/* offsets that must read back as all zeroes in verify mode */
static struct io zeroes[] = {
	{1048576, 4096},				/* block 256 */
	{20480, 4096},					/* block 5 */
	{5ULL * 1024 * 1024 * 1024, 4096},		/* block 1310720 */
};

#define MAXIO 16384

static int write_phase(const char *host, const char *port, const char *name) {
	char buf[MAXIO];
	uint64_t size;
	uint32_t error;
	unsigned i;
	int sock;

	sock = negotiate(host, port, name, &size);
	if (sock < 0)
		return -1;
	if (size != EXPSIZE) {
		fprintf(stderr, "unexpected export size %" PRIu64
				", expected %" PRIu64 "\n",
				(uint64_t)size, (uint64_t)EXPSIZE);
		return -1;
	}
	printf("export size is %" PRIu64 " as expected\n",
			(uint64_t)size);
	for (i = 0; i < sizeof(ios) / sizeof(ios[0]); i++) {
		fill_pattern(buf, ios[i].off, ios[i].len);
		if (do_request(sock, NBD_CMD_WRITE, ios[i].off, ios[i].len,
				buf, NULL, &error)) {
			fprintf(stderr, "write at %" PRIu64 " failed: %s\n",
					ios[i].off, errstr);
			return -1;
		}
		if (error) {
			fprintf(stderr, "write at %" PRIu64
					" returned error %" PRIu32 "\n",
					ios[i].off, error);
			return -1;
		}
	}
	if (do_request(sock, NBD_CMD_FLUSH, 0, 0, NULL, NULL, &error)) {
		fprintf(stderr, "flush failed: %s\n", errstr);
		return -1;
	}
	if (error) {
		fprintf(stderr, "flush returned error %" PRIu32 "\n", error);
		return -1;
	}
	do_request(sock, NBD_CMD_DISC, 0, 0, NULL, NULL, NULL);
	close(sock);
	printf("wrote %u ranges\n", (unsigned)(sizeof(ios) / sizeof(ios[0])));
	return 0;
}

static int check_range(int sock, uint64_t off, uint32_t len, int expect_zero) {
	char buf[MAXIO];
	char *checkbuf = malloc(len);
	uint32_t error;

	if (!checkbuf)
		return -1;
	if (do_request(sock, NBD_CMD_READ, off, len, NULL, checkbuf,
			&error)) {
		fprintf(stderr, "read at %" PRIu64 " failed: %s\n",
				off, errstr);
		free(checkbuf);
		return -1;
	}
	if (error) {
		fprintf(stderr, "read at %" PRIu64
				" returned error %" PRIu32 "\n", off, error);
		free(checkbuf);
		return -1;
	}
	if (expect_zero) {
		memset(buf, 0, len);
	} else {
		fill_pattern(buf, off, len);
	}
	if (memcmp(buf, checkbuf, len)) {
		uint32_t j;

		for (j = 0; j < len; j++)
			if (buf[j] != checkbuf[j]) {
				fprintf(stderr, "mismatch at offset %" PRIu64
					": got 0x%02x, expected 0x%02x\n",
					off + j,
					(unsigned char)checkbuf[j],
					(unsigned char)buf[j]);
				break;
			}
		free(checkbuf);
		return -1;
	}
	free(checkbuf);
	return 0;
}

static int verify_phase(const char *host, const char *port, const char *name) {
	uint64_t size;
	unsigned i;
	int sock;

	/* a new connection, to prove the data is in the tree and not
	 * in some per-connection cache */
	sock = negotiate(host, port, name, &size);
	if (sock < 0)
		return -1;
	if (size != EXPSIZE) {
		fprintf(stderr, "unexpected export size %" PRIu64 "\n",
				(uint64_t)size);
		return -1;
	}
	for (i = 0; i < sizeof(ios) / sizeof(ios[0]); i++)
		if (check_range(sock, ios[i].off, ios[i].len, 0))
			return -1;
	for (i = 0; i < sizeof(zeroes) / sizeof(zeroes[0]); i++)
		if (check_range(sock, zeroes[i].off, zeroes[i].len, 1))
			return -1;
	do_request(sock, NBD_CMD_DISC, 0, 0, NULL, NULL, NULL);
	close(sock);
	printf("all written ranges read back correctly; "
			"unwritten ranges are zeroes\n");
	return 0;
}

/*
 * Write four full blocks, trim most of them (unaligned), and check
 * that the trimmed parts now read back as zeroes while the untrimmed
 * parts are left alone.
 */
static int trim_phase(const char *host, const char *port, const char *name) {
	char buf[4096];
	uint64_t size;
	uint32_t error;
	int i;
	int sock;

	sock = negotiate(host, port, name, &size);
	if (sock < 0)
		return -1;
	for (i = 0; i < 4; i++) {
		fill_pattern(buf, i * 4096, 4096);
		if (do_request(sock, NBD_CMD_WRITE, i * 4096, 4096, buf,
				NULL, &error) || error) {
			fprintf(stderr, "trimtest: write block %d failed\n",
					i);
			return -1;
		}
	}
	/* trim [100, 12388): part of block 0, all of blocks 1 and 2,
	 * and part of block 3 */
	if (do_request(sock, NBD_CMD_TRIM, 100, 12288, NULL, NULL, &error)) {
		fprintf(stderr, "trimtest: trim failed: %s\n", errstr);
		return -1;
	}
	if (error) {
		fprintf(stderr, "trimtest: trim returned error %" PRIu32
				"\n", error);
		return -1;
	}
	if (do_request(sock, NBD_CMD_FLUSH, 0, 0, NULL, NULL, &error)
			|| error) {
		fprintf(stderr, "trimtest: flush failed\n");
		return -1;
	}
	/* the untrimmed edges must still hold the old data */
	if (check_range(sock, 0, 100, 0))
		return -1;
	/* the trimmed range must read back as zeroes */
	if (check_range(sock, 100, 12288, 1))
		return -1;
	/* and so must the part of block 3 that was never written */
	if (check_range(sock, 12388, 4096 - 100, 0))
		return -1;
	do_request(sock, NBD_CMD_DISC, 0, 0, NULL, NULL, NULL);
	close(sock);
	printf("trim behaves as expected\n");
	return 0;
}

/* write the expected pattern for a given range to stdout, so it can
 * be compared against a block file on disk */
static int expect_phase(uint64_t off, uint32_t len) {
	char buf[MAXIO];

	while (len) {
		uint32_t chunk = len > MAXIO ? MAXIO : len;

		fill_pattern(buf, off, chunk);
		if (xwrite(STDOUT_FILENO, buf, chunk))
			return -1;
		off += chunk;
		len -= chunk;
	}
	return 0;
}

