static int connect_server(const char *host, const char *port) {
	struct addrinfo hints, *ai, *res;
	int sock = -1;
	int e;

	memset(&hints, 0, sizeof(hints));
	hints.ai_family = AF_UNSPEC;
	hints.ai_socktype = SOCK_STREAM;
	if ((e = getaddrinfo(host, port, &hints, &res))) {
		fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(e));
		return -1;
	}
	/* try all resolved addresses (e.g. both ::1 and 127.0.0.1 for
	 * localhost), the server may be listening on only one of
	 * them */
	for (ai = res; ai; ai = ai->ai_next) {
		sock = socket(ai->ai_family, ai->ai_socktype,
				ai->ai_protocol);
		if (sock < 0)
			continue;
		if (connect(sock, ai->ai_addr, ai->ai_addrlen) == 0)
			break;
		close(sock);
		sock = -1;
	}
	if (sock < 0) {
		fprintf(stderr, "connect to %s port %s: %s\n", host, port,
				strerror(errno));
		errstr = strerror(errno);
	}
	freeaddrinfo(res);
	return sock;
}

