/**
 * Punch a hole in the block files of a treefiles export (if supported
 * by the current system). Blocks fully contained in the trim range
 * have their block file removed entirely; for blocks partially
 * contained in the range, only the trimmed bytes are discarded.
 *
 * @param req the request for which this is being processed
 * @param client the client for which we're processing this request
 **/
static int exptrim_treefiles(struct nbd_request* req, CLIENT* client) {
	off_t from = req->from;
	off_t end = from + (off_t)req->len;
	off_t blk;

	for(blk = from / TREEPAGESIZE; blk * TREEPAGESIZE < end; blk++) {
		off_t blkstart = blk * TREEPAGESIZE;

		if(from <= blkstart && blkstart + TREEPAGESIZE <= end) {
			/* the whole block is unused, drop the file */
			delete_treefile(client->exportname,
					(off_t)client->exportsize, blkstart);
		} else {
			/* the block is only partially unused, discard
			 * the unused part of it only */
			off_t ppos = from > blkstart ? from - blkstart : 0;
			off_t pend = end < blkstart + TREEPAGESIZE ?
				end - blkstart : TREEPAGESIZE;
